/**
 * Utility Functions for Skills Lookup, Search, and Filtering
 */

// Search skills across name, aliases, category, and subcategory
export function searchTechSkills(query: string, categoryFilter?: SkillCategoryName | 'All'): TechSkill[] {
  const clean = query.trim().toLowerCase();
  
  return TECH_SKILLS_DATABASE.filter((skill) => {
    if (categoryFilter && categoryFilter !== 'All' && skill.category !== categoryFilter) {
      return false;
    }
    if (!clean) return true;

    const nameMatch = skill.name.toLowerCase().includes(clean);
    const catMatch = skill.category.toLowerCase().includes(clean);
    const subMatch = skill.subcategory?.toLowerCase().includes(clean) || false;
    const aliasMatch = skill.aliases.some((a) => a.toLowerCase().includes(clean));

    return nameMatch || catMatch || subMatch || aliasMatch;
  });
}

// Get all skills grouped by category
export function getSkillsGroupedByCategory(): Record<SkillCategoryName, TechSkill[]> {
  const grouped: Record<string, TechSkill[]> = {};
  SKILL_CATEGORIES.forEach((cat) => {
    grouped[cat] = [];
  });
  TECH_SKILLS_DATABASE.forEach((skill) => {
    if (!grouped[skill.category]) {
      grouped[skill.category] = [];
    }
    grouped[skill.category].push(skill);
  });
  return grouped as Record<SkillCategoryName, TechSkill[]>;
}

// Find a skill by its unique ID or display name
export function findSkillByIdOrName(identifier: string): TechSkill | undefined {
  const lower = identifier.trim().toLowerCase();
  return TECH_SKILLS_DATABASE.find(
    (s) =>
      s.id.toLowerCase() === lower ||
      s.name.toLowerCase() === lower ||
      s.aliases.some((a) => a.toLowerCase() === lower)
  );
}

// Helper to get formatted display name from any legacy or new skill string
export function formatSkillDisplayName(rawSkill: string): string {
  const matched = findSkillByIdOrName(rawSkill);
  return matched ? matched.name : rawSkill;
}
